question_text:
Яким буде результат виконання наступного коду в строгому режимі (strict mode)?
```javascript
'use strict';
function test() {
  console.log(typeof foo);
  if (true) {
    function foo() { return 1; }
  }
  console.log(typeof foo);
}
test();
```

Яким буде результат виконання наступного коду?
```javascript
let x = 1;
function outer() {
  let x = 2;
  function inner() {
    console.log(x);
  }
  x = 3;
  return inner;
}
const fn = outer();
fn();
```

Яким буде результат виконання наступного коду?
```javascript
const arr = [];
for (var i = 0; i < 3; i++) {
  arr.push(() => i);
}
const arr2 = [];
for (let j = 0; j < 3; j++) {
  arr2.push(() => j);
}
console.log(arr[1](), arr2[1]());
```

Яким буде результат виконання наступного коду?
```javascript
var x = 10;
function test() {
  console.log(x);
  if (false) {
    var x = 20;
  }
}
test();
```

Яким буде результат виконання наступного коду?
```javascript
var x = 1;
{
  var x = 2;
  let y = 3;
}
console.log(x);
console.log(typeof y);
```

Яким буде результат виконання наступного коду?
```javascript
let x = 10;
{
  console.log(x);
  let x = 20;
}
```

Яким буде результат виконання наступного коду?
```javascript
(function() {
  var a = b = 3;
})();
console.log(typeof a);
console.log(typeof b);
```

Яким буде результат виконання наступного коду?
```javascript
var x = 1;
function test(x = x) {
  console.log(x);
}
test();
```

Яким буде результат виконання наступного коду?
```javascript
const f = function g() {
  console.log(typeof g);
};
f();
console.log(typeof g);
```

Яким буде результат виконання наступного коду?
```javascript
function test(a, b = 2) {
  a = 10;
  console.log(arguments[0]);
}
test(1);
```

Яким буде результат виконання наступного коду?
```javascript
var x = 1;
let y = 2;
console.log(globalThis.hasOwnProperty('x'));
console.log(globalThis.hasOwnProperty('y'));
```

Яким буде результат виконання наступного коду?
```javascript
'use strict';
let x = 1;
function test() {
  eval('var x = 2; console.log(x);');
}
test();
console.log(x);
```

Яким буде результат виконання наступного коду?
```javascript
let a = 1;
{
  let a = 2;
  function f() {
    console.log(a);
  }
}
f();
```

Яким буде результат виконання наступного коду?
```javascript
try {
  throw new Error('fail');
} catch (x) {
  var x = 1;
  let y = 2;
  console.log(x);
}
console.log(x);
console.log(typeof y);
```

Яким буде результат виконання наступного коду?
```javascript
function test() {
  const arr = [];
  for (let i = 0; i < 3; i++) {
    arr.push(() => {
      console.log(i);
    });
  }
  return arr;
}
const funcs = test();
funcs[0]();
funcs[1]();
```

Яким буде результат виконання наступного коду?
```javascript
const obj = {};
Object.defineProperty(obj, 'x', {
  value: 42,
  writable: true,
  configurable: false,
  enumerable: true
});
Object.defineProperty(obj, 'x', {
  writable: false
});
console.log(obj.x);
Object.defineProperty(obj, 'x', {
  value: 99
});
```

Яким буде результат виконання наступного коду?
```javascript
const proto = {
  set value(val) {
    this._val = val * 2;
  }
};
const obj = Object.create(proto);
obj.value = 10;
console.log(obj.value, obj._val);
```

