  greet() { return 'Hello'; }
};
class BaseClass {}
class ChildClass extends Mixin(BaseClass) {}
const inst = new ChildClass();
console.log(inst instanceof BaseClass);
console.log(inst instanceof ChildClass);
```

Яким буде результат виконання наступного коду?
```javascript
