Яким буде результат виконання наступного коду? (ES2022+)
```javascript
class Tester {
  #val = 42;
  compare(other) {
    return other.#val;
  }
}
const t1 = new Tester();
const t2 = new Tester();
console.log(t1.compare(t2));
```

Яким буде результат виконання наступного коду?
```javascript
function Base() {
  this.x = 1;
}
function Custom() {}
const obj = Reflect.construct(Base, [], Custom);
console.log(obj.x);
console.log(Object.getPrototypeOf(obj) === Custom.prototype);
```

Яким буде результат виконання наступного коду?
```javascript
const obj = {
  x: 42,
  getX() {
    const inner = () => this.x;
    return inner;
  }
};
const detached = obj.getX();
console.log(detached.call({ x: 99 }));
```

Яким буде результат виконання наступного коду?
```javascript
function test() {
  console.log(this.val);
}
const bound = test.bind({ val: 1 }).bind({ val: 2 });
bound();
```

Яким буде результат виконання наступного коду?
```javascript
function curried(a) {
  const fn = (b) => curried(a + b);
  fn.toString = () => a;
  fn.valueOf = () => a;
  return fn;
}
console.log(Number(curried(1)(2)(3)));
```

Яким буде результат виконання наступного коду в нестрогому режимі (non-strict mode)?
```javascript
function test() {
  return this;
}
console.log(test.call(undefined) === globalThis);
console.log(test.call(42) instanceof Number);
```

Яким буде результат виконання наступного коду?
```javascript
function* genA() {
  yield 1;
  return 'doneA';
}
function* genB() {
  const val = yield* genA();
  yield val;
}
const it = genB();
console.log(it.next().value);
```

Яким буде результат виконання наступного коду?
```javascript
const myAsyncIterable = {
  [Symbol.asyncIterator]() {
    let count = 0;
    return {
      async next() {
        if (count < 2) {
          return { value: count++, done: false };
        }
        return { value: undefined, done: true };
      }
    };
  }
};
(async () => {
  let res = '';
  for await (const x of myAsyncIterable) {
    res += x;
  }
  console.log(res);
})();
```

Яким буде результат виконання наступного коду?
```javascript
const slice = Function.prototype.call.bind(Array.prototype.slice);
const result = slice({ 0: 'a', 1: 'b', length: 2 });
console.log(Array.isArray(result));
console.log(result[1]);
```

Яким буде результат виконання наступного коду?
```javascript
function* gen() {
  try {
    yield 1;
  } catch (err) {
    yield err;
  }
}
const g = gen();
console.log(g.next().value);
console.log(g.throw('error').value);
```

Яким буде результат виконання наступного коду?
```javascript
const partial = (fn, ...args) => (...rest) => fn(...args.map(x => x === '_' ? rest.shift() : x).concat(rest));
const greet = (g, name) => `${g}, ${name}!`;
const greetHello = partial(greet, 'Hello', '_');
console.log(greetHello('Alice'));
```

Яким буде результат виконання наступного коду?
