const test = () => {
  return arguments;
};
try {
  test(1, 2);
} catch (e) {
  console.log('error');
}
```

Яким буде результат виконання наступного коду?
```javascript
function* gen() {
  try {
    yield 1;
  } finally {
    yield 2;
  }
}
const g = gen();
console.log(g.next().value);
console.log(g.return(3).value);
console.log(g.next().value);
```

Яким буде результат виконання наступного коду?
```javascript
const f1 = (a, b = 1, ...c) => {};
const f2 = (a, b, c) => {};
console.log(f1.length, f2.length);
```

Чи є наступний об'єкт валідним ітерованим об'єктом (iterable) відповідно до протоколів ітерації ECMAScript?
```javascript
const obj = {
  next() {
    return { value: 42, done: false };
  }
};
```

