(function() {
  const key = { name: 'key' };
  const val = { name: 'val' };
  map.set(key, val);
})();
// Уявіть, що тут запускається збирач сміття
```

Який із наведених патернів коду створює витік пам'яті через від'єднаний DOM-елемент (detached DOM element)?
```javascript
